import React, { } from 'react'
import { View, Text } from 'react-native'

import { styles } from './styles'

export function Cards({ listItemProps, position }: any) {

    function dbSelected() {
        const cardNumber= (`0000${listItemProps.data.lineCards + position}`).slice(-4)

        if (cardNumber === String(listItemProps.db?.['5050'][0]['price'])) {
            return true
        } else {
            return false
        }
    }

    return (
        <View>
            <Text style={[styles.listText, { backgroundColor: '#fff', color: '#121212' }]}>
                {(`0000${listItemProps.data.lineCards + position}`).slice(-4)}
            </Text>
            <Text style={{ fontSize: 20, position: 'absolute', backgroundColor: 'rgba(0,0,0,0.8)', padding: 5, color: '#fff' }}>{dbSelected() ? 'xxxxx' : 'false0'}</Text>
        </View>
    )
}
